-- PS-005.4 agrega endpoints MySQL y gateway SSH al esquema portal del Portal.
-- Alcance: solo añade cinco columnas nullable y dos restricciones a client_connection_profiles.
-- Las columnas permanecen NULL para perfiles legacy; no se modifica ninguna otra tabla.
-- Reversión: volver al release anterior conserva esta migración y sus datos; no eliminar endpoints.
ALTER TABLE "portal"."client_connection_profiles" ADD COLUMN "destination_hostname" varchar(253);--> statement-breakpoint
ALTER TABLE "portal"."client_connection_profiles" ADD COLUMN "destination_port" integer;--> statement-breakpoint
ALTER TABLE "portal"."client_connection_profiles" ADD COLUMN "gateway_hostname" varchar(253);--> statement-breakpoint
ALTER TABLE "portal"."client_connection_profiles" ADD COLUMN "gateway_port" integer;--> statement-breakpoint
ALTER TABLE "portal"."client_connection_profiles" ADD COLUMN "gateway_fingerprint" varchar(50);--> statement-breakpoint
ALTER TABLE "portal"."client_connection_profiles" ADD CONSTRAINT "client_connection_profiles_destination_endpoint_check" CHECK (("portal"."client_connection_profiles"."destination_hostname" IS NULL AND "portal"."client_connection_profiles"."destination_port" IS NULL) OR ("portal"."client_connection_profiles"."destination_hostname" IS NOT NULL AND btrim("portal"."client_connection_profiles"."destination_hostname") <> '' AND "portal"."client_connection_profiles"."destination_port" BETWEEN 1 AND 65535));--> statement-breakpoint
ALTER TABLE "portal"."client_connection_profiles" ADD CONSTRAINT "client_connection_profiles_gateway_endpoint_check" CHECK (("portal"."client_connection_profiles"."destination_hostname" IS NULL AND "portal"."client_connection_profiles"."destination_port" IS NULL AND "portal"."client_connection_profiles"."gateway_hostname" IS NULL AND "portal"."client_connection_profiles"."gateway_port" IS NULL AND "portal"."client_connection_profiles"."gateway_fingerprint" IS NULL) OR ("portal"."client_connection_profiles"."profile_type" = 'MYSQL_TCP' AND "portal"."client_connection_profiles"."destination_hostname" IS NOT NULL AND "portal"."client_connection_profiles"."destination_port" BETWEEN 1 AND 65535 AND "portal"."client_connection_profiles"."gateway_hostname" IS NULL AND "portal"."client_connection_profiles"."gateway_port" IS NULL AND "portal"."client_connection_profiles"."gateway_fingerprint" IS NULL) OR ("portal"."client_connection_profiles"."profile_type" = 'MYSQL_SSH' AND "portal"."client_connection_profiles"."destination_hostname" IS NOT NULL AND "portal"."client_connection_profiles"."destination_port" BETWEEN 1 AND 65535 AND "portal"."client_connection_profiles"."gateway_hostname" IS NOT NULL AND btrim("portal"."client_connection_profiles"."gateway_hostname") <> '' AND "portal"."client_connection_profiles"."gateway_port" BETWEEN 1 AND 65535 AND "portal"."client_connection_profiles"."gateway_fingerprint" ~ '^SHA256:[A-Za-z0-9+/]{43}$'));
